class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        if x == 0:
            return 0

        res = float('inf')
        S = []

        i = 0
        while i < len(nums):
            if i >= x - 1:
                S.append(nums[i - (x - 1)])

            j = bisect.bisect_left(S, nums[i])
            if j < len(S):
                res = min(res, abs(S[j] - nums[i]))
            if j > 0:
                res = min(res, abs(S[j - 1] - nums[i]))

            i += 1

        return res
